fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    // If the array is empty, return two empty arrays
    if len == 0 {
        return (Vec::new(), Vec::new());
    }
    
    // If the array has only one element, we cannot split it into two non-empty arrays
    if len == 1 {
        return (Vec::new(), a);
    }
    
    // Split the array into two parts
    let mid = len / 2;
    let first_part = a[..mid].to_vec();
    let second_part = a[mid..].to_vec();
    
    (first_part, second_part)
}